        return;
    }
    if ($a[$N-1] == 15) {
        echo "DOWN\n";
        return;
    }
}

function readToken() {
    static $tokens = array();
    while (empty($tokens)) {
        $line = fgets(STDIN);
        if ($line === false) {
            return null;
        }
        $tokens = preg_split('/\s+/', trim($line), -1, PREG_SPLIT_NO_EMPTY);
    }
    return array_shift($tokens);
}

main();
